`timescale 1ns/100ps

// Zybo Z7-20 bitstream #2: PL RISC-V + PS DDR via HP0 AXI-Lite.
// design_1_wrapper is generated by Vivado from bd/create_bd.tcl.
module fpga_top_ps (
  // Zynq DDR / FIXED_IO (must be top-level)
  inout  wire [14:0] DDR_addr,
  inout  wire [2:0]  DDR_ba,
  inout  wire        DDR_cas_n,
  inout  wire        DDR_ck_n,
  inout  wire        DDR_ck_p,
  inout  wire        DDR_cke,
  inout  wire        DDR_cs_n,
  inout  wire [3:0]  DDR_dm,
  inout  wire [31:0] DDR_dq,
  inout  wire [3:0]  DDR_dqs_n,
  inout  wire [3:0]  DDR_dqs_p,
  inout  wire        DDR_odt,
  inout  wire        DDR_ras_n,
  inout  wire        DDR_reset_n,
  inout  wire        DDR_we_n,
  inout  wire        FIXED_IO_ddr_vrn,
  inout  wire        FIXED_IO_ddr_vrp,
  inout  wire [53:0] FIXED_IO_mio,
  inout  wire        FIXED_IO_ps_clk,
  inout  wire        FIXED_IO_ps_porb,
  inout  wire        FIXED_IO_ps_srstb,

  input  logic       btn_reset_i,
  output logic [3:0] led_o,
  output logic       uart_tx_o
);

  logic clk_i;
  logic fclk_resetn;
  logic [0:0] cpu_run_bus;
  logic       cpu_run;
  logic [3:0] rst_sync;
  logic       rst_ni_sys, rst_ni;

  logic [31:0] S_AXI_awaddr, S_AXI_wdata, S_AXI_araddr, S_AXI_rdata;
  logic [2:0]  S_AXI_awprot, S_AXI_arprot;
  logic [3:0]  S_AXI_wstrb;
  logic [1:0]  S_AXI_bresp, S_AXI_rresp;
  logic        S_AXI_awvalid, S_AXI_awready, S_AXI_wvalid, S_AXI_wready;
  logic        S_AXI_bvalid, S_AXI_bready, S_AXI_arvalid, S_AXI_arready;
  logic        S_AXI_rvalid, S_AXI_rready;

  design_1_wrapper u_bd (
    .DDR_addr         (DDR_addr),
    .DDR_ba           (DDR_ba),
    .DDR_cas_n        (DDR_cas_n),
    .DDR_ck_n         (DDR_ck_n),
    .DDR_ck_p         (DDR_ck_p),
    .DDR_cke          (DDR_cke),
    .DDR_cs_n         (DDR_cs_n),
    .DDR_dm           (DDR_dm),
    .DDR_dq           (DDR_dq),
    .DDR_dqs_n        (DDR_dqs_n),
    .DDR_dqs_p        (DDR_dqs_p),
    .DDR_odt          (DDR_odt),
    .DDR_ras_n        (DDR_ras_n),
    .DDR_reset_n      (DDR_reset_n),
    .DDR_we_n         (DDR_we_n),
    .FIXED_IO_ddr_vrn (FIXED_IO_ddr_vrn),
    .FIXED_IO_ddr_vrp (FIXED_IO_ddr_vrp),
    .FIXED_IO_mio     (FIXED_IO_mio),
    .FIXED_IO_ps_clk  (FIXED_IO_ps_clk),
    .FIXED_IO_ps_porb (FIXED_IO_ps_porb),
    .FIXED_IO_ps_srstb(FIXED_IO_ps_srstb),
    .FCLK_CLK0        (clk_i),
    .FCLK_RESET0_N    (fclk_resetn),
    .cpu_run          (cpu_run_bus),
    .S_AXI_awaddr     (S_AXI_awaddr),
    .S_AXI_awprot     (S_AXI_awprot),
    .S_AXI_awvalid    (S_AXI_awvalid),
    .S_AXI_awready    (S_AXI_awready),
    .S_AXI_wdata      (S_AXI_wdata),
    .S_AXI_wstrb      (S_AXI_wstrb),
    .S_AXI_wvalid     (S_AXI_wvalid),
    .S_AXI_wready     (S_AXI_wready),
    .S_AXI_bresp      (S_AXI_bresp),
    .S_AXI_bvalid     (S_AXI_bvalid),
    .S_AXI_bready     (S_AXI_bready),
    .S_AXI_araddr     (S_AXI_araddr),
    .S_AXI_arprot     (S_AXI_arprot),
    .S_AXI_arvalid    (S_AXI_arvalid),
    .S_AXI_arready    (S_AXI_arready),
    .S_AXI_rdata      (S_AXI_rdata),
    .S_AXI_rresp      (S_AXI_rresp),
    .S_AXI_rvalid     (S_AXI_rvalid),
    .S_AXI_rready     (S_AXI_rready)
  );

  always_ff @(posedge clk_i or negedge fclk_resetn) begin
    if (!fclk_resetn)
      rst_sync <= 4'b0000;
    else if (btn_reset_i)
      rst_sync <= 4'b0000;
    else
      rst_sync <= {rst_sync[2:0], 1'b1};
  end
  assign rst_ni_sys = rst_sync[3];
  assign cpu_run    = cpu_run_bus[0];
  // cpu_run (AXI GPIO from PS/XSCT): 0 = hold core reset for FW load
  assign rst_ni = rst_ni_sys && cpu_run;

  logic        ireq, ignt, irvalid;
  logic [31:0] iaddr, irdata;
  logic        dreq, dwe, dgnt, drvalid;
  logic [3:0]  dbe;
  logic [31:0] daddr, dwdata, drdata;
  logic        error;

  logic        mem_req, uart_req, gpio_req;
  logic        mem_gnt, uart_gnt, gpio_gnt;
  logic        mem_rvalid, uart_rvalid, gpio_rvalid;
  logic [31:0] mem_rdata, uart_rdata, gpio_rdata;

  logic        a_req, a_we, a_gnt, a_rvalid;
  logic [3:0]  a_be;
  logic [31:0] a_addr, a_wdata, a_rdata;

  logic [3:0]  gpio_led;
  logic [24:0] hb_q;

  core u_core (
    .clk_i,
    .rst_ni,
    .instr_req_o    (ireq),
    .instr_addr_o   (iaddr),
    .instr_gnt_i    (ignt),
    .instr_rvalid_i (irvalid),
    .instr_rdata_i  (irdata),
    .data_req_o     (dreq),
    .data_we_o      (dwe),
    .data_be_o      (dbe),
    .data_addr_o    (daddr),
    .data_wdata_o   (dwdata),
    .data_gnt_i     (dgnt),
    .data_rvalid_i  (drvalid),
    .data_rdata_i   (drdata),
    .irq_timer_i    (1'b0),
    .irq_ext_i      (1'b0),
    .error_o        (error)
  );

  logic is_uart, is_gpio;
  assign is_uart = (daddr[31:16] == 16'h1000) && (daddr[15:12] == 4'h0);
  assign is_gpio = (daddr[31:16] == 16'h1000) && (daddr[15:12] == 4'h2);

  assign mem_req  = dreq && !is_uart && !is_gpio;
  assign uart_req = dreq && is_uart;
  assign gpio_req = dreq && is_gpio;

  always_comb begin
    if (is_uart) begin
      dgnt = uart_gnt; drvalid = uart_rvalid; drdata = uart_rdata;
    end else if (is_gpio) begin
      dgnt = gpio_gnt; drvalid = gpio_rvalid; drdata = gpio_rdata;
    end else begin
      dgnt = mem_gnt; drvalid = mem_rvalid; drdata = mem_rdata;
    end
  end

  mem_arbiter u_arb (
    .clk_i, .rst_ni,
    .i_req_i(ireq), .i_addr_i(iaddr),
    .i_gnt_o(ignt), .i_rvalid_o(irvalid), .i_rdata_o(irdata),
    .d_req_i(mem_req), .d_we_i(dwe), .d_be_i(dbe),
    .d_addr_i(daddr), .d_wdata_i(dwdata),
    .d_gnt_o(mem_gnt), .d_rvalid_o(mem_rvalid), .d_rdata_o(mem_rdata),
    .m_req_o(a_req), .m_we_o(a_we), .m_be_o(a_be),
    .m_addr_o(a_addr), .m_wdata_o(a_wdata),
    .m_gnt_i(a_gnt), .m_rvalid_i(a_rvalid), .m_rdata_i(a_rdata)
  );

  axi_req_adapter u_axi (
    .clk_i, .rst_ni,
    .req_i(a_req), .we_i(a_we), .be_i(a_be),
    .addr_i(a_addr), .wdata_i(a_wdata),
    .gnt_o(a_gnt), .rvalid_o(a_rvalid), .rdata_o(a_rdata),
    .m_axi_awaddr (S_AXI_awaddr),
    .m_axi_awprot (S_AXI_awprot),
    .m_axi_awvalid(S_AXI_awvalid),
    .m_axi_awready(S_AXI_awready),
    .m_axi_wdata  (S_AXI_wdata),
    .m_axi_wstrb  (S_AXI_wstrb),
    .m_axi_wvalid (S_AXI_wvalid),
    .m_axi_wready (S_AXI_wready),
    .m_axi_bresp  (S_AXI_bresp),
    .m_axi_bvalid (S_AXI_bvalid),
    .m_axi_bready (S_AXI_bready),
    .m_axi_araddr (S_AXI_araddr),
    .m_axi_arprot (S_AXI_arprot),
    .m_axi_arvalid(S_AXI_arvalid),
    .m_axi_arready(S_AXI_arready),
    .m_axi_rdata  (S_AXI_rdata),
    .m_axi_rresp  (S_AXI_rresp),
    .m_axi_rvalid (S_AXI_rvalid),
    .m_axi_rready (S_AXI_rready)
  );

  uart_tx #(.ClkHz(50_000_000), .Baud(115_200)) u_uart (
    .clk_i, .rst_ni,
    .req_i(uart_req), .we_i(dwe), .be_i(dbe),
    .addr_i(daddr), .wdata_i(dwdata),
    .gnt_o(uart_gnt), .rvalid_o(uart_rvalid), .rdata_o(uart_rdata),
    .uart_tx_o(uart_tx_o)
  );

  gpio_leds u_gpio (
    .clk_i, .rst_ni,
    .req_i(gpio_req), .we_i(dwe), .be_i(dbe),
    .addr_i(daddr), .wdata_i(dwdata),
    .gnt_o(gpio_gnt), .rvalid_o(gpio_rvalid), .rdata_o(gpio_rdata),
    .led_o(gpio_led)
  );

  // Heartbeat while core held in reset (cpu_run=0): LD0 blinks
  always_ff @(posedge clk_i) begin
    if (!rst_ni_sys)
      hb_q <= '0;
    else
      hb_q <= hb_q + 25'd1;
  end
  assign led_o = cpu_run ? gpio_led : {3'b000, hb_q[24]};

  logic _unused;
  assign _unused = error;

endmodule
